import{_ as a,o as t,c as o,ae as s}from"./chunks/framework.B2FZg54p.js";const r="/heidrun/experiments/web-doc-by-ai/documentation_images/workspaces/status_bar_workspace.svg",i="/heidrun/experiments/web-doc-by-ai/documentation_images/workspaces/workspace_information_card.svg",m=JSON.parse('{"title":"Create and switch workspaces","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/create_and_switch_workspaces.md","filePath":"documentation/create_and_switch_workspaces.md"}'),n={name:"documentation/create_and_switch_workspaces.md"};function c(p,e,h,l,w,d){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="create-and-switch-workspaces" tabindex="-1">Create and switch workspaces <a class="header-anchor" href="#create-and-switch-workspaces" aria-label="Permalink to &quot;Create and switch workspaces&quot;">​</a></h1><p>Create a workspace from a folder, select it, and switch to another workspace when you need a different project.</p><h2 id="create-and-select-a-workspace" tabindex="-1">Create and select a workspace <a class="header-anchor" href="#create-and-select-a-workspace" aria-label="Permalink to &quot;Create and select a workspace&quot;">​</a></h2><p>A workspace is a project folder. The folder name becomes the workspace name. The workspace status bar section is at the bottom left of the Heidrun window and shows the selected workspace name.</p><p><img src="'+r+'" alt="The workspace status bar section at the bottom left of the Heidrun window."></p><ol><li>Click the workspace name in the workspace status bar section to open the workspace information card.</li><li>Click <strong>New workspace…</strong> at the bottom of the workspace information card.</li><li>Choose a folder in the folder chooser.</li><li>Click the workspace name in the workspace status bar section to reopen the workspace information card.</li><li>Select the new workspace by its folder name in the list.</li></ol><p>The workspace information card closes, and the workspace status bar section shows the selected workspace name. Creating a workspace adds it to the list; select its row to switch to it.</p><p><img src="'+i+'" alt="Workspace rows and the New workspace… entry in the workspace information card."></p><h2 id="switch-workspaces" tabindex="-1">Switch workspaces <a class="header-anchor" href="#switch-workspaces" aria-label="Permalink to &quot;Switch workspaces&quot;">​</a></h2><ol><li>Click the name in the workspace status bar section at the bottom left to open the workspace information card.</li><li>Click the row for the workspace you want to use.</li></ol><p>The workspace information card closes, and the chosen workspace name appears in the workspace status bar section.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><section class="documentation-troubleshooting-topic" aria-label="The new workspace is listed, but its name does not appear in the workspace status bar section"><h3 id="the-new-workspace-is-listed-but-its-name-does-not-appear-in-the-workspace-status-bar-section" tabindex="-1">The new workspace is listed, but its name does not appear in the workspace status bar section <a class="header-anchor" href="#the-new-workspace-is-listed-but-its-name-does-not-appear-in-the-workspace-status-bar-section" aria-label="Permalink to &quot;The new workspace is listed, but its name does not appear in the workspace status bar section&quot;">​</a></h3><p><strong>Cause</strong>: Creating a workspace adds it to the list without selecting it.</p><p><strong>Solution</strong>:</p><ol><li>Click the workspace name in the workspace status bar section to open the workspace information card.</li><li>Click the row with the new workspace name.</li></ol><p><strong>Check</strong>: The workspace information card closes and the new workspace name appears in the workspace status bar section.</p></section><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="/heidrun/experiments/web-doc-by-ai/documentation/tabs.html">Create, select and rename tabs</a>: to continue work with tabs in the selected workspace.</li><li><a href="/heidrun/experiments/web-doc-by-ai/documentation/pane_focus_history.html">Return to a previously focused pane</a>: to move between panes in the selected workspace.</li></ul>',15)])])}const u=a(n,[["render",c]]);export{m as __pageData,u as default};
